def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    Args:
        separator (str, optional): Delimits values, the default is comma.
        header (str, optional): First string of the output.
    """
    if header:
        header = [header]
    else:
        header = []
    for point in self.points:
        csv_row = header.copy()
        for coord in point.coords:
            csv_row.append(str(coord))
            for value in point.values:
                csv_row.append(str(value))
        csv_row.append("\n")

    return "".join(csv_row)

