def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Together with update_last_applied_manifest_list_from_resp(), this function is called recursively to update a partial last_applied_manifest from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial last_applied_manifest being updated
        observer_schema (dict): partial observer_schema
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in last_applied_manifest if they are not yet present

    """

    for field, value in response.items():
        if field in observer_schema:
            if field not in last_applied_manifest:
                last_applied_manifest[field] = value
            else:
                if isinstance(value, dict):
                    update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], observer_schema[field], value)
                else:
                    last_applied_manifest[field] = value
        else:
            raise KeyError(f"The observed field {field} is not present in the Kubernetes response")

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:`update_last_applied_manifest_list_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """

    for field, field_spec in observer_schema.items():
        if field not in response:
            raise KeyError(f'Missing field {field} in Kubernetes response')
        field_value = response[field]
        if isinstance(field_value, dict):
            if field not in last_applied_manifest:
                last_applied_manifest[field] = {}
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], field_spec, field_value)
        elif isinstance(field_value, list):
            if field not in last_applied_manifest:
                last_applied_manifest[field] = []
            update_last_applied_manifest_list_from_resp(last_applied_manifest[field], field_spec, field_value)
        else:
            last_applied_manifest[field] = field_value

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Together with ``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present
    """
    for key, value in observer_schema.items():
        if key == "Conditions":
            if "Conditions" not in response:
                raise KeyError("Conditions key not present in Kubernetes response")
            for condition in response["Conditions"]:
                if condition["Type"] not in last_applied_manifest:
                    last_applied_manifest[condition["Type"]] = condition["Status"]
        elif key == "LastTransitionTime":
            if "LastTransitionTime" not in response:
                raise KeyError("LastTransitionTime key not present in Kubernetes response")
            last_applied_manifest[key] = response[key]
        elif key in ("Items", "ObservedGeneration"):
            if key not in last_applied_manifest:
                last_applied_manifest[key] = value
        else:
            if key not in last_applied_manifest:
                last_applied_manifest[key] = value

