def format(sql, params):
    # Convert sql to out-style parameters
    # Replace any in-style parameters with $1, $2, $\3, ...
    formatted_sql = re.sub(r"(?<![a-zA-Z0-9_])[?]", r"$", sql)

    # Replace any named in-style parameters with $n where n is the index of the parameter in the params list
    for i, param in enumerate(params):
        formatted_sql = formatted_sql.replace(param, "$" + str(i + 1))

    # Convert params to out-style parameters
    # Take each item in the params list and make it a dictionary of {"$1": value, "$2": value, ...}
    out_params = {}
    for i, param in enumerate(params):
        out_params["$" + str(i + 1)] = param

    return (formatted_sql, out_params)

