        logger.error(f"Path {path} does not exist.")
        return False
    elif not os.path.is_dir(path):
        logger.error(f"Path {path} is not a directory.")
        return False

    dir_structure = os.listdir(path)

    for entry in dir_structure:
        if entry == 'cp-info.yaml':
            continue
        path = os.path.join(path, entry)

        if entry == '.keep':
            continue

        if not validate_header(path):
            logger.error(f"cp-info.yaml is missing or invalid in {path} {entry}.")
            return False

        if not validate_metadata(path):
