def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        if not commands:
            raise ValueError("No commands were specified")
        if not args:
            raise ValueError("No arguments were specified")
        if not isinstance(commands, list):
            raise TypeError("The commands parameter must be a list")
        if not isinstance(args, list):
            raise TypeError("The args parameter must be a list")
        if not (callable(commands[0]) or isinstance(commands[0], str)):
            raise TypeError("The command must be a callable object or a string")
        if not (isinstance(args[0], str) or isinstance(args[0], list)):
            raise TypeError("The args must be a string or a list of strings")
        if cwd and not isinstance(cwd, str):
            raise TypeError("The cwd parameter must be a string")
        if verbose and not isinstance(verbose, bool):
            raise TypeError("The verbose parameter must be a boolean")
        if hide_stderr and not isinstance(hide_stderr, bool):
            raise TypeError("The hide_stderr parameter must be a boolean")
        if env and not isinstance(env, dict):
            raise TypeError("The env parameter must be a dictionary")
    except:
        raise

    process = subprocess.Popen(
        commands,
        args,
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE if hide_stderr else None,
        env=env,
    )
    output, error = process.communicate()

    if verbose:
        print(output.decode())

    return output.decode().strip()


