            content_digests = set(root_inventory.get('content_digests', []))
            updated_content_digests = []
            for digest, content_metadata in inventory.items():
                if digest not in content_digests:
                    updated_content_digests.append(digest)
            if updated_content_digests:
                self.updated_content_digests.extend(updated_content_digests)
        return self.updated_content_digests

def validate_version_inventories(self, version_dirs):
        for version_dir in version_dirs:
            inventory_file = version_dir + ".version.inventory"
            if not os.path.exists(inventory_file):
                raise InvalidInventoryError("Inventory file " + inventory_file + " is missing for version " + version_dir)

            inventory_digest = self.digest(inventory_file)
            if inventory_digest not in self.version_inventories[version_dir]:
                raise InconsistentInventoryError("Inventory file " + inventory_file + " has incorrect digest for version " + version_dir + ". Expected: " + self.version_inventories[version_dir] + " but got: " + inventory_digest)

            for content_dir in os.listdir(version_dir):
                if content_dir not in self.version_inventories[version_dir]:
                    self.version_inventories[version_dir][content_dir] = self.digest(version_dir + "/" + content_dir)
                elif self.version_inventories[version_dir][content_dir] != self.digest(version_dir + "/" + content_dir):
                    self.version_inventories[version_dir][content_dir] = self.digest(version_dir + "/" + content_dir)
                    if content_dir not in self.changed_content_digests:
                        self.changed_content_digests[content_dir] = []
                    self.changed_content_digests[content_dir].append(self.version_inventories[version_dir][content_dir])

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Arguments:
    path (str): a path that you want to discover the type of

    Return values:
    'root' - looks like an OCFL Storage Root
    'object' - looks like an OCFL Object
    'file' - a file, might be an inventory
    other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if os.path.isdir(path):
        # Check for 0=* files
        for f in os.listdir(path):
            if f.startswith("0="):
                return "root"
        # If no 0=* files found, check for jp2 files
        for f in os.listdir(path):
            if f.endswith(".jp2"):
                return "object"
        # If no jp2 files found, check for file names that begin with "0="
        for f in os.listdir(path):
            if f.startswith("0="):
                return "object"
        # If no files starting with "0=" found, it's not an OCFL root
        return "other"
    elif os.path.isfile(path):
        if path.endswith(".jp2"):
            return "object"
        elif path.startswith("0="):
            return "object"
        else:
            return "file"
    else:
        return "other"

