def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Args:
        path: A path-like object representing the directory or file to check.

    Returns:
        'root', 'object', 'file', or some other error message.

    """
    # Look only at "0=*" Namaste files to determine the directory type
    if os.path.isdir(path):
        namaste_file = os.path.join(path, "0=*")
        if os.path.isfile(namaste_file):
            with open(namaste_file, "r") as f:
                lines = f.readlines()
                for line in lines:
                    fields = line.split(" ")
                    if fields[0] == "format=ocfl_1.0":
                        return "root"
                    elif fields[0] == "format=ocfl_object_1.0":
                        return "object"
                    elif fields[0] == "format=ocfl_file_1.0":
                        return "file"
                    else:
                        return "Unknown format " + fields[0]
        else:
            return "Invalid namaste file"
    else:
        return "Invalid path specified"

def find_path_type(path):
    if os.path.isdir(path) and "0=*" in os.listdir(path):
        try:
            ocf = OrderedContentFile.from_root(path)
            if "0=root" in ocf.members:
                return "root"
            else:
                return "object"
        except ValueError:
            return "error: not a valid root"
    elif os.path.isfile(path) and path.endswith(".txt"):
        try:
            with open(path, "r") as f:
                contents = f.read()
                if "content-type: text/plain" in contents:
                    return "file"
                else:
                    return "error: not a text file"
        except IOError:
            return "error: unable to open file"
    else:
        return "error: not a recognized typ"

