def deep_merge(source, destination):
    for key, value in source.items():
        if isinstance(value, dict):
            # dict: merge dictionaries recursively
            if key in destination and isinstance(destination[key], dict):
                deep_merge(value, destination[key])
            else:
                destination[key] = value
        else:
            # non-dict: overwrite the existing value
            destination[key] = value
    return destination

def deep_merge_nodes(nodes):
    # Convert the list of tuples to a dictionary for easy look-up
    nodes_dict = dict(nodes)

    for key, value in nodes_dict.items():
        # Check if the value is a MappingNode (dict-like)
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            # Get the corresponding value (if any) in the original nodes
            corresponding_value = nodes_dict.get(key)
            # If the corresponding value is also a MappingNode (dict-like)
            if corresponding_value and isinstance(corresponding_value, ruamel.yaml.nodes.MappingNode):
                # Merge the two mapping nodes (dicts) by recursively merging their key-value pairs
                merged_value = deep_merge_nodes([(key, value), (key, corresponding_value)])
                # Update the value in the original nodes dictionary
                nodes_dict[key] = merged_value

    # Return the resulting concatenated list
    return list(nodes_dict.items())

def deep_merge_nodes(nodes):
    result_nodes = []
    for node in nodes:
        if len(node) == 2:
            key, value = node
            if isinstance(value, ruamel.yaml.nodes.MappingNode) and any(result_node[0] == key for result_node in result_nodes):
                result_node = next(result_node for result_node in result_nodes if result_node[0] == key)
                result_value = result_node[1]
                for sub_key, sub_value in value.value:
                    if sub_key not in result_value:
                        result_value.append(sub_key, sub_value)
                    else:
                        result_sub_value = result_value[sub_key]
                        if isinstance(sub_value, ruamel.yaml.nodes.MappingNode) and isinstance(result_sub_value, ruamel.yaml.nodes.MappingNode):
                            result_sub_value.value.extend(sub_value.value)
                        else:
                            result_sub_value.value = sub_value.value
                result_node[1] = result_value
            else:
                result_nodes.append(node)
        else:
            result_nodes.append(node)
    return result_nodes

def deep_merge_nodes(nodes):
    def deep_dict_merge(d1, d2):
        for k in set(d1).union(d2):
            if k in d1 and k in d2:
                if isinstance(d1[k], dict) and isinstance(d2[k], dict):
                    yield (deep_dict_merge(d1[k], d2[k]), )
                    continue
            yield from (d2.get(k, d1[k] if k in d1 else None), )
    merged = dict(deep_dict_merge(nodes[0][1].value, nodes[1][1].value))
    return [(nodes[0][0], ruamel.yaml.nodes.MappingNode(tag='tag:yaml.org,2002:map', value=merged))]

