def deep_merge_nodes(nodes):
    from collections import defaultdict

    merged_nodes = defaultdict(list)
    for node in nodes:
        key, value = node[0], node[1]
        if type(value) == MappingNode:
            for child in value.value:
                child_key, child_value = child[0], child[1]
                if type(child_value) == MappingNode:
                    child_key.value = deep_merge_nodes([(value, child_value)])[0]
                merged_nodes[key].append(child_key)
        else:
            merged_nodes[key].append(value)

    return [
        (
            key,
            MappingNode(
                tag="tag:yaml.org,2002:map",
                value=[
                    (key, value) for key, value in merged_nodes[key_]
                ],
            ),
        )
        for key_ in merged_nodes.keys()
    ]

