def bash_completion():
        '''
        Return a bash completion script for the borgmatic command. Produce this by introspecting
        borgmatic's command-line argument parsers.
        '''

        import borgmatic.cli
        import borgmatic.misc

        def __doc_str(method):
            doc = ''
            for line in method[0].split('\n'):
                if line.strip().startswith(':/'):
                    doc += line.lstrip(':/').strip() + '\n'
            return doc.strip()

        class AutoCompleter:
            def __init__(self, parser):
                self.parser = parser

            def generate_completion(self, prefix):
                completion = ''
                for action in self.parser._actions:
                    name = action.dest
                    if name is None:
                        continue

                    names = [name]
                    if isinstance(action, borgmatic.cli.FlagsGroup):
                        names = action.args
                    elif isinstance(action, borgmatic.cli.BorgmaticArgumentParser):
                        names = [action.prog]

                    for name in names:
                        if name.startswith(prefix):
                            abbrev = name.replace('-', '')
                            doc = ''
                            if action.help:
                                doc = action.help
                            elif getattr(action, '_func', None):
                                doc = __doc_str(getattr(action, '_func'))
                            completion += '{},{}\n'.format(name, doc)
                return completion

        completer = AutoCompleter(borgmatic.cli.BorgmaticArgumentParser.boring_commands())
        completer = AutoCompleter(borgmatic.cli.BorgmaticArgumentParser.restore_commands())
        completer = AutoCompleter(borgmatic.cli.BorgmaticArgumentParser.storage_commands())
        completions = completer.generate_completion('borgmatic-')

        # fixup borgmatic commands
        completions = completions.replace('borgmatic-', '

