def paging(response, max_results):
    yield response[0:max_results]
    for i in range(1, len(response) // max_results):
        yield response[i * max_results:i * max_results + max_results]

def size_to_bytes(size: str) -> int:
    if re.match(r'^\d+$', size):
        return int(size)
    elif re.match(r'^\d+[KMG]$', size):
        num = int(size[:-1])
        if size[-1] == 'K':
            return num * 1000
        elif size[-1] == 'M':
            return num * 1000000
        else:
            return num * 1000000000
