def vertex3tuple(vertices):
    """return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex.

    :param vertices: A list of vertices that make up the polygon
    :type vertices: list of :class:`Vertex` objects
    :return: A list of 3 tuples that represent the 3 points for each vertex. The first tuple contains the vertex, the second tuple contains the point on the left, and the third tuple contians the point on the right.
    :rtype: list of (Vertex, Vertex, Vertex)
    """
    if not isinstance(vertices, list):
        raise ValueError("Invalid input: vertices must be a list of Vertex objects")

    output = []
    for v in vertices:
        if not isinstance(v, Vertex):
            raise ValueError("Invalid input: vertices must be a list of Vertex objects")

        left = None
        right = None
        previous = None
        next = None
        for i in range(len(vertices)):
            if v == vertices[i]:
                if i > 0:
                    previous = vertices[i - 1]
                if i < len(vertices) - 1:
                    next = vertices[i + 1]
                break

        if previous and next:
            left = previous
            right = next

        output.append((v, left, right))

    return output

