def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """

    if roots is None:
        roots = set()
    for child, parent in graph.subject_objects(predicate=prop):
        if not graph.objects(subject=parent, predicate=prop):
            roots.add(parent)
        else:
            roots.update(find_roots(graph, prop, roots))
    return roots

def find_roots(graph: rdflib.Graph, prop: rdflib.URIRef, roots: Optional[Set[rdflib.Node]] = None) -> Set[rdflib.Node]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf) will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()
    for subject, _, object in graph.triples((None, prop, None)):
        if object not in graph and object not in roots:
            roots.add(subject)
            find_roots(graph, prop, roots)
    return roots

def find_roots(graph, prop, roots=None):
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()
    for triple in graph:
        if triple[1] == prop:
            if triple[2] not in roots:
                roots.add(triple[2])
    return roots

