    def from_ticks(cls, ticks, tz=None):
        """Create a time from ticks (nanoseconds since midnight).

        Parameters:
            ticks (int): The number of nanoseconds since midnight.
            tz (datetime.tzinfo): Optional timezone.

        Returns:
            Time: A new Time object representing the given time.

        Raises:
            ValueError: If the ticks value is out of bounds (0 <= ticks < 86400000000000).
        """
        if ticks < 0 or ticks >= 86400000000000:
            raise ValueError("The ticks value must be between 0 and 86400000000000, inclusive.")
        if tz is not None and isinstance(tz, datetime.tzinfo):
            return cls(datetime.time(hour=0, minute=0, second=0, microsecond=0), tz=tz) + datetime.timedelta(microseconds=ticks)
        return cls(datetime.time(hour=0, minute=0, second=0, microsecond=0)) + datetime.timedelta(microseconds=ticks)

