def verifyClass(iface, candidate, tentative=False):
    """Verify that *candidate* implements the given interface *iface*.

    If *tentative* is ``True``, check if the candidate implements *iface*
    partially, meaning some of the methods of *iface* are not implemented.
    If *tentative* is ``False`` (default), the method raises a ``TypeError``
    if *candidate* does not implement *iface* completely.
    """
    iface_attrs = dir(iface)
    for attr in iface_attrs:
        if not hasattr(candidate, attr):
            raise TypeError("Missing attribute '%s' in %s" % (attr, candidate))
        if not callable(getattr(candidate, attr)):
            raise TypeError("'%s' is not callable in %s" % (attr, candidate))

    # Check if the candidate implements the given interface partially
    if not tentative:
        candidate_attrs = dir(candidate)
