            dt_str = dt_str.replace("Z", "+0000")

        # parse the datetime
        try:
            dt = datetime.datetime.strptime(dt_str, "%Y-%m-%dT%H:%M:%S.%f%z")
        except ValueError:
            # try again, this time without the optional sub-second components
            dt = datetime.datetime.strptime(dt_str, "%Y-%m-%dT%H:%M:%S%z")

